<section class="page-head"><div><p class="eyebrow">Pengelolaan Air</p><h2>Hasil Simulasi</h2><p>Setiap hasil menggunakan snapshot data saat simulasi dijalankan.</p></div><a class="btn btn-primary" href="<?=url('water-simulation')?>"><i class="bi bi-plus-lg"></i> Simulasi Baru</a></section>
<div class="panel"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Nomor/Nama</th><th>Tanggal</th><th>Musim</th><th>Debit Efektif</th><th>Kebutuhan</th><th>Selisih</th><th>Terpenuhi</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9"><div class="empty-state"><i class="bi bi-clipboard-data"></i><h4>Belum ada hasil</h4><p>Jalankan simulasi untuk membuat hasil pertama.</p></div></td></tr><?php endif?><?php foreach($rows as $row):?><tr><td><strong><?=e($row['simulation_number'])?></strong><small class="d-block text-secondary"><?=e($row['name'])?></small></td><td><?=e($row['simulation_date'])?></td><td><?=e(ucfirst($row['season']))?></td><td><?=number_format((float)$row['total_effective_flow_lps'],2,',','.')?> L/s</td><td><?=number_format((float)$row['total_demand_lps'],2,',','.')?> L/s</td><td class="<?=$row['surplus_deficit_lps']<0?'text-danger':'text-success'?>"><?=number_format((float)$row['surplus_deficit_lps'],2,',','.')?></td><td><?=number_format((float)$row['fulfillment_percent'],1,',','.')?>%</td><td><span class="water-status <?=e($row['result_status']??'draft')?>"><?=e(ucfirst($row['result_status']??'draft'))?></span></td><td><a class="btn btn-sm btn-outline-primary" href="<?=url('water-results/'.$row['id'])?>">Detail</a></td></tr><?php endforeach?></tbody></table></div></div>

